const html = String($input.first().json.data || $input.first().json.body || '');
const status = $input.first().json.statusCode || null;
const base = $('Prepara richiesta').first().json.url;
const pick = (re) => { const m = html.match(re); return m ? m[1].trim() : ''; };
const dec = (s) => s
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#39;|&apos;|&rsquo;/g, "'").replace(/&agrave;/g, 'à').replace(/&egrave;/g, 'è')
  .replace(/&eacute;/g, 'é').replace(/&igrave;/g, 'ì').replace(/&ograve;/g, 'ò').replace(/&ugrave;/g, 'ù')
  .replace(/&euro;/g, '€').replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
  .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCharCode(parseInt(n, 16)));
const hostOf = (u) => { const x = String(u).match(/^https?:\/\/([^\/?#:]+)/i); return x ? x[1].toLowerCase().replace(/^www\./, '') : ''; };
const origin = (base.match(/^(https?:\/\/[^\/?#]+)/i) || [, ''])[1];
const abs = (h0) => { const h = dec(String(h0)).trim(); if (!h || h.startsWith('#')) return ''; if (/^[a-z][a-z0-9+.-]*:/i.test(h)) return h; if (h.startsWith('//')) return 'https:' + h; if (h.startsWith('/')) return origin + h; return base.replace(/[?#].*$/, '').replace(/[^\/]*$/, '') + h; };

const titolo = dec(pick(/<title[^>]*>([\s\S]*?)<\/title>/i)).replace(/\s+/g, ' ').trim();
const descrizione = dec(pick(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i) || pick(/<meta[^>]+content=["']([^"']*)["'][^>]+name=["']description["']/i));

let body = html
  .replace(/<!--[\s\S]*?-->/g, '')
  .replace(/<(script|style|noscript|svg|template|iframe|head)[\s\S]*?<\/\1>/gi, '');

const linkSet = new Set();
const linkRe = /<a\b[^>]*href=["']([^"'#][^"']*)["'][^>]*>/gi;
let m;
while ((m = linkRe.exec(body))) { const u = abs(m[1]); if (u.startsWith('http') || u.startsWith('mailto:') || u.startsWith('tel:')) linkSet.add(u); }
const links = [...linkSet];
const host = hostOf(base);
const interni = links.filter(l => hostOf(l) === host);
const esterni = links.filter(l => l.startsWith('http') && !interni.includes(l));
const social = esterni.filter(l => /instagram\.com|facebook\.com|tiktok\.com|linkedin\.com|youtube\.com|wa\.me|whatsapp\.com/i.test(l));

let md = body
  .replace(/<h([1-6])[^>]*>([\s\S]*?)<\/h\1>/gi, (_, n, t) => '\n\n' + '#'.repeat(Number(n)) + ' ' + t.replace(/<[^>]+>/g, ' ').trim() + '\n\n')
  .replace(/<a\b[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi, (_, h, t) => { const tx = t.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(); const u = abs(h); return tx ? (u && !u.startsWith('javascript') ? `[${tx}](${u})` : tx) : ''; })
  .replace(/<img\b[^>]*alt=["']([^"']+)["'][^>]*>/gi, (_, a) => ` (immagine: ${a}) `)
  .replace(/<li[^>]*>/gi, '\n- ')
  .replace(/<(br|hr)\s*\/?>/gi, '\n')
  .replace(/<\/(p|div|section|article|header|footer|ul|ol|table|tr|h[1-6]|blockquote|main|nav|form)>/gi, '\n\n')
  .replace(/<\/(td|th)>/gi, ' | ')
  .replace(/<[^>]+>/g, ' ');
md = dec(md).replace(/[ \t ]+/g, ' ').replace(/ *\n */g, '\n').replace(/\n{3,}/g, '\n\n').trim();

const testoPiatto = md.replace(/\[([^\]]*)\]\([^)]*\)/g, '$1');
const email = [...new Set((html.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || []).map(e => e.toLowerCase()).filter(e => !/\.(png|jpe?g|webp|gif|svg)$/.test(e) && !/sentry|wixpress|example\./.test(e)))];
const telefoni = [...new Set((testoPiatto.match(/(?<![\d+])(?:\+39[\s.]?)?(?:3\d{2}|0[1-9]\d{0,2})[\s./-]?\d{3,4}[\s./-]?\d{3,4}(?!\d)/g) || []).map(t => t.replace(/[\s./-]/g, '').replace(/^\+39/, '')).filter(t => t.length >= 9 && t.length <= 11))];

for (const l of links) if (l.startsWith('tel:')) { const t = decodeURIComponent(l.slice(4)).replace(/[\s./-]/g, '').replace(/^\+39/, ''); if (!telefoni.includes(t)) telefoni.push(t); }
const MAX = Number($('Prepara richiesta').first().json.max_caratteri) || 60000;
return [{ json: {
  ok: status ? status < 400 : html.length > 0,
  url: base, stato_http: status, fonte: 'diretto',
  titolo, descrizione,
  caratteri: testoPiatto.length,
  serve_browser: testoPiatto.length < 400,
  markdown: md.slice(0, MAX), troncato: md.length > MAX,
  email, telefoni, social,
  link_interni: interni.slice(0, 300), link_esterni: esterni.slice(0, 200),
  letto_il: new Date().toISOString(),
} }];

const prima = $('Pulisci in Markdown').first().json;
const r = $input.first().json || {};
if (!r.ok || !r.markdown || (r.caratteri || 0) <= (prima.caratteri || 0)) {
  return [{ json: { ...prima, nota: r.errore || r.nota || 'Motore: nessun testo in più. Usare il browser integrato o Scrapling sul PC.' } }];
}
const unici = (a) => [...new Set(a.filter(Boolean))];
return [{ json: {
  ...prima,
  ...r,
  ok: true,
  fonte: 'motore-' + (r.fonte || 'browser'),
  email: unici([...(prima.email || []), ...(r.email || [])]),
  telefoni: unici([...(prima.telefoni || []), ...(r.telefoni || [])]),
} }];
